    //    W_q'=W_q·P_k, W_k'=W_k·P_k, W_v'=W_v·P_v, W_o=W_o·P_v^T
    //    P_k, P_v generated offline via cosine similarity grouping

    // Step 2: Vector Splitting
    for i in 1..m:  // m=32 subvectors
        K_sub[i] = K[:, (i-1)*d/m : i*d/m]  // [N, d/m]
